1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	</style>
52	</head>
53	<body>
54	<main>
55	  <h1>Todos</h1>
56	  <form id="todo-form">
57	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
58	    <button type="submit" data-testid="todo-add">Add</button>
59	  </form>
60	  <ul data-testid="todo-list"></ul>
61	</main>
62	<script>
63	(function () {
64	  var STORAGE_KEY = 'todos';
65	  var form = document.getElementById('todo-form');
66	  var input = document.querySelector('[data-testid="todo-input"]');
67	  var list = document.querySelector('[data-testid="todo-list"]');
68	
69	  // [REQ-001]
70	  function makeId() {
71	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
72	      return window.crypto.randomUUID();
73	    }
74	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
75	  }
76	
77	  // [REQ-001]
78	  function loadTodos() {
79	    try {
80	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
81	      return Array.isArray(parsed) ? parsed : [];
82	    } catch (e) {
83	      return [];
84	    }
85	  }
86	
87	  // [REQ-001]
88	  function saveTodos() {
89	    try {
90	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
91	    } catch (e) {}
92	  }
93	
94	  var todos = loadTodos();
95	
96	  // [REQ-001]
97	  function render() {
98	    list.textContent = '';
99	    todos.forEach(function (todo) {
100	      var li = document.createElement('li');
101	      li.setAttribute('data-testid', 'todo-item');
102	      li.setAttribute('data-id', todo.id);
103	
104	      var text = document.createElement('span');
105	      text.setAttribute('data-testid', 'todo-text');
106	      text.textContent = todo.text;
107	
108	      var del = document.createElement('button');
109	      del.type = 'button';
110	      del.setAttribute('data-testid', 'todo-delete');
111	      del.setAttribute('aria-label', 'Delete todo');
112	      del.textContent = 'Delete';
113	      del.addEventListener('click', function () { deleteTodo(todo.id); });
114	
115	      li.appendChild(text);
116	      li.appendChild(del);
117	      list.appendChild(li);
118	    });
119	  }
120	
121	  // [REQ-001]
122	  function addTodo(text) {
123	    text = text.trim();
124	    if (!text) return;
125	    todos.push({ id: makeId(), text: text, createdAt: Date.now() });
126	    saveTodos();
127	    render();
128	  }
129	
130	  // [REQ-001]
131	  function deleteTodo(id) {
132	    todos = todos.filter(function (t) { return t.id !== id; });
133	    saveTodos();
134	    render();
135	  }
136	
137	  form.addEventListener('submit', function (e) {
138	    e.preventDefault();
139	    addTodo(input.value);
140	    input.value = '';
141	    input.focus();
142	  });
143	
144	  render();
145	})();
146	</script>
147	</body>
148	</html>
